const items = $input.all();
const fechaHoy = new Date().toLocaleString('es-CO', { timeZone: 'America/Bogota' });
const msgRaw = $('Telegram Trigger: Mensaje Entrante').first().json.message;
const textoAndres = msgRaw.text || '¿Qué citas tengo?';

const citas = items.map(i => i.json).filter(j => j && j.cliente);

return [{
  json: {
    chat_id: msgRaw.chat.id,
    pregunta_andres: textoAndres,
    fecha_actual: fechaHoy,
    citas: citas,
    resumen_citas_texto: JSON.stringify(citas, null, 2)
  }
}];

